#' Hematologic Prognostic Indices
#'
#' Derives the commonly reported blood-count and inflammation-based prognostic 
#' indices from routine complete-blood-count and biochemistry variables: the 
#' neutrophil-to-lymphocyte ratio (NLR), platelet-to-lymphocyte ratio (PLR), 
#' lymphocyte-to-monocyte ratio (LMR), systemic immune-inflammation index 
#' (SII), Onodera's Prognostic Nutritional Index (PNI), the 
#' C-reactive-protein-to-albumin ratio (CAR), and the (modified) Glasgow 
#' Prognostic Score (GPS / mGPS). Each index is computed per patient, 
#' summarized across the cohort, optionally dichotomized at a literature or 
#' data-driven cutpoint, and optionally related to a survival outcome.
#' 
#'
#' @examples
#' \donttest{
#' hematologicindices(
#'     data = mydata,
#'     neutrophils = "neut", lymphocytes = "lymph",
#'     platelets = "plt", albumin = "alb", crp = "crp")
#'}
#' @param data The data as a data frame (one row per patient).
#' @param neutrophils Absolute neutrophil count (10^9/L).
#' @param lymphocytes Absolute lymphocyte count (10^9/L).
#' @param platelets Platelet count (10^9/L).
#' @param monocytes Absolute monocyte count (10^9/L), for LMR.
#' @param albumin Serum albumin in g/dL (for PNI). If your data are in g/L,
#'   set the albumin unit.
#' @param albuminUnit Unit of the albumin variable.
#' @param crp C-reactive protein in mg/L (for CAR and GPS).
#' @param indices Which indices to compute (subject to the required inputs
#'   being supplied).
#' @param gpsType Original GPS scores low albumin even with normal CRP; mGPS
#'   requires elevated CRP.
#' @param survivalTime Follow-up time, to relate an index to outcome.
#' @param survivalStatus Event indicator for the survival linkage.
#' @param eventLevel Level of the status variable representing the event.
#' @param survivalIndex Which continuous index to dichotomize for the survival
#'   comparison.
#' @param splitMethod How to dichotomize the chosen index for the survival
#'   split.
#' @param showIndicesTable Summary statistics for each computed index.
#' @param showSurvival Compare survival above vs below the cutpoint of the
#'   chosen index.
#' @param showPlot Plot the index distributions (or survival split).
#' @param showSummary Plain-language summary.
#' @param showExplanation Formulas and cut points.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$indicesTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$gpsTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$survivalTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$addIndexToData} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$indicesTable$asDF}
#'
#' \code{as.data.frame(results$indicesTable)}
#'
#' @export
hematologicindices <- function(
    data,
    neutrophils,
    lymphocytes,
    platelets,
    monocytes = NULL,
    albumin = NULL,
    albuminUnit = "gdl",
    crp = NULL,
    indices = list(
                "nlr",
                "plr",
                "sii",
                "pni"),
    gpsType = "modified",
    survivalTime = NULL,
    survivalStatus = NULL,
    eventLevel,
    survivalIndex = "nlr",
    splitMethod = "median",
    showIndicesTable = TRUE,
    showSurvival = FALSE,
    showPlot = TRUE,
    showSummary = FALSE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("hematologicindices requires jmvcore to be installed (restart may be required)")

    if ( ! missing(neutrophils)) neutrophils <- jmvcore::resolveQuo(jmvcore::enquo(neutrophils))
    if ( ! missing(lymphocytes)) lymphocytes <- jmvcore::resolveQuo(jmvcore::enquo(lymphocytes))
    if ( ! missing(platelets)) platelets <- jmvcore::resolveQuo(jmvcore::enquo(platelets))
    if ( ! missing(monocytes)) monocytes <- jmvcore::resolveQuo(jmvcore::enquo(monocytes))
    if ( ! missing(albumin)) albumin <- jmvcore::resolveQuo(jmvcore::enquo(albumin))
    if ( ! missing(crp)) crp <- jmvcore::resolveQuo(jmvcore::enquo(crp))
    if ( ! missing(survivalTime)) survivalTime <- jmvcore::resolveQuo(jmvcore::enquo(survivalTime))
    if ( ! missing(survivalStatus)) survivalStatus <- jmvcore::resolveQuo(jmvcore::enquo(survivalStatus))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(neutrophils), neutrophils, NULL),
            `if`( ! missing(lymphocytes), lymphocytes, NULL),
            `if`( ! missing(platelets), platelets, NULL),
            `if`( ! missing(monocytes), monocytes, NULL),
            `if`( ! missing(albumin), albumin, NULL),
            `if`( ! missing(crp), crp, NULL),
            `if`( ! missing(survivalTime), survivalTime, NULL),
            `if`( ! missing(survivalStatus), survivalStatus, NULL))


    options <- hematologicindicesOptions$new(
        neutrophils = neutrophils,
        lymphocytes = lymphocytes,
        platelets = platelets,
        monocytes = monocytes,
        albumin = albumin,
        albuminUnit = albuminUnit,
        crp = crp,
        indices = indices,
        gpsType = gpsType,
        survivalTime = survivalTime,
        survivalStatus = survivalStatus,
        eventLevel = eventLevel,
        survivalIndex = survivalIndex,
        splitMethod = splitMethod,
        showIndicesTable = showIndicesTable,
        showSurvival = showSurvival,
        showPlot = showPlot,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- hematologicindicesClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

